## 2. Complete, Compilable Implementation

```cpp
#define _GNU_SOURCE
#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <atomic>
#include <thread>
#include <chrono>
#include <cstring>
#include <cstdint>
#include <cassert>
#include <coroutine>
#include <array>
#include <optional>
#include <random>
#include <algorithm>
#include <mutex>
#include <condition_variable>
#include <span>

#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <liburing.h>

#if defined(__x86_64__) || defined(_M_X64)
#include <nmmintrin.h>
#endif

// ============================================================================
// CONSTANTS & SYSTEM CONFIGURATION
// ============================================================================
static constexpr uint64_t INF_TX_ID = UINT64_MAX;
static constexpr size_t MAX_SKIPLIST_LEVELS = 32;
static constexpr float SKIPLIST_P = 0.5f;
static constexpr size_t CACHE_LINE_SIZE = 64;
static constexpr size_t ALIGN_BLOCK_SIZE = 4096;
static constexpr size_t WAL_RING_BUFFER_CAPACITY = 64 * 1024; // 64K log slots
static constexpr size_t IO_URING_QUEUE_DEPTH = 512;
static constexpr size_t MAX_THREADS = 128;
static constexpr size_t EBR_EPOCHS = 3;

// ============================================================================
// HARDWARE-ACCELERATED CRC32C
// ============================================================================
inline uint32_t calculate_crc32c(uint32_t initial, const uint8_t* data, size_t length) {
    uint32_t crc = ~initial;
#if defined(__x86_64__) || defined(_M_X64)
    size_t i = 0;
    while (i + 8 <= length) {
        uint64_t val;
        std::memcpy(&val, data + i, sizeof(uint64_t));
        crc = static_cast<uint32_t>(_mm_crc32_u64(crc, val));
        i += 8;
    }
    while (i < length) {
        crc = _mm_crc32_u8(crc, data[i]);
        i++;
    }
#else
    // Standard software CRC32C (Castagnoli polynomial 0x82F63B78)
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int b = 0; b < 8; ++b) {
            crc = (crc >> 1) ^ (0x82F63B78u & (-(crc & 1u)));
        }
    }
#endif
    return ~crc;
}

// ============================================================================
// EPOCH-BASED RECLAMATION (EBR)
// ============================================================================
struct alignas(CACHE_LINE_SIZE) EpochThreadControl {
    std::atomic<uint64_t> local_epoch{INF_TX_ID}; // INF_TX_ID means inactive
    std::atomic<bool> is_active{false};
};

class EpochManager {
public:
    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
        RetiredNode* next;
    };

    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    EpochManager() : global_epoch_(0), thread_slots_{} {}

    ~EpochManager() {
        for (size_t ep = 0; ep < EBR_EPOCHS; ++ep) {
            reclaim_epoch(ep);
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (thread_slots_[i].is_active.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded MAX_THREADS registration limit in EpochManager");
    }

    void unregister_thread(size_t slot) {
        assert(slot < MAX_THREADS);
        thread_slots_[slot].local_epoch.store(INF_TX_ID, std::memory_order_release);
        thread_slots_[slot].is_active.store(false, std::memory_order_release);
    }

    void enter_quiescent_region(size_t slot) {
        const uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);
        thread_slots_[slot].local_epoch.store(g_epoch, std::memory_order_release);
    }

    void exit_quiescent_region(size_t slot) {
        thread_slots_[slot].local_epoch.store(INF_TX_ID, std::memory_order_release);
    }

    void retire(void* ptr, void (*deleter)(void*), size_t thread_slot) {
        if (!ptr) return;
        const uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t bucket = g_epoch % EBR_EPOCHS;

        auto* node = new RetiredNode{ptr, deleter, nullptr};
        RetiredNode* head = thread_retired_[thread_slot][bucket].load(std::memory_order_relaxed);
        do {
            node->next = head;
        } while (!thread_retired_[thread_slot][bucket].compare_exchange_weak(
            head, node, std::memory_order_acq_rel, std::memory_order_relaxed));
    }

    void try_advance_and_reclaim() {
        const uint64_t current_g_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have witnessed current_g_epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (thread_slots_[i].is_active.load(std::memory_order_relaxed)) {
                uint64_t th_epoch = thread_slots_[i].local_epoch.load(std::memory_order_acquire);
                if (th_epoch != INF_TX_ID && th_epoch < current_g_epoch) {
                    return; // Thread still in older epoch; cannot advance
                }
            }
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(
                const_cast<uint64_t&>(current_g_epoch), current_g_epoch + 1,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            // Safely reclaim 2 epochs behind (current_g_epoch + 1 - 2 = current_g_epoch - 1)
            size_t safe_bucket = (current_g_epoch + 1 - 2) % EBR_EPOCHS;
            reclaim_epoch(safe_bucket);
        }
    }

    uint64_t get_min_active_epoch() const {
        uint64_t min_epoch = global_epoch_.load(std::memory_order_acquire);
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (thread_slots_[i].is_active.load(std::memory_order_relaxed)) {
                uint64_t th_epoch = thread_slots_[i].local_epoch.load(std::memory_order_acquire);
                if (th_epoch != INF_TX_ID && th_epoch < min_epoch) {
                    min_epoch = th_epoch;
                }
            }
        }
        return min_epoch;
    }

private:
    void reclaim_epoch(size_t bucket) {
        for (size_t t = 0; t < MAX_THREADS; ++t) {
            RetiredNode* head = thread_retired_[t][bucket].exchange(nullptr, std::memory_order_acq_rel);
            while (head) {
                RetiredNode* next = head->next;
                head->deleter(head->ptr);
                delete head;
                head = next;
            }
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_;
    std::array<EpochThreadControl, MAX_THREADS> thread_slots_;
    alignas(CACHE_LINE_SIZE) std::atomic<RetiredNode*> thread_retired_[MAX_THREADS][EBR_EPOCHS]{};
};

thread_local size_t tl_thread_id = EpochManager::instance().register_thread();

struct EpochGuard {
    EpochGuard() {
        EpochManager::instance().enter_quiescent_region(tl_thread_id);
    }
    ~EpochGuard() {
        EpochManager::instance().exit_quiescent_region(tl_thread_id);
        EpochManager::instance().try_advance_and_reclaim();
    }
};

// ============================================================================
// PART 1: LATCH-FREE MVCC SKIP-LIST INDEX
// ============================================================================

struct alignas(CACHE_LINE_SIZE) VersionRecord {
    uint64_t created_tx_id;
    uint64_t deleted_tx_id;
    uint32_t val_size;
    std::atomic<VersionRecord*> next_version;
    uint8_t payload[1]; // Flexible array member

    static VersionRecord* allocate(uint64_t created_tx, uint64_t deleted_tx, std::span<const uint8_t> data) {
        size_t total_size = sizeof(VersionRecord) + (data.empty() ? 0 : data.size() - 1);
        void* raw_mem = nullptr;
        if (posix_memalign(&raw_mem, CACHE_LINE_SIZE, total_size) != 0) {
            throw std::bad_alloc();
        }
        auto* rec = reinterpret_cast<VersionRecord*>(raw_mem);
        rec->created_tx_id = created_tx;
        rec->deleted_tx_id = deleted_tx;
        rec->val_size = static_cast<uint32_t>(data.size());
        rec->next_version.store(nullptr, std::memory_order_relaxed);
        if (!data.empty()) {
            std::memcpy(rec->payload, data.data(), data.size());
        }
        return rec;
    }

    static void deallocate(void* ptr) {
        std::free(ptr);
    }
};

template <typename Key = uint64_t>
class alignas(CACHE_LINE_SIZE) SkipListNode {
public:
    struct MarkedPointer {
        uintptr_t value;

        SkipListNode* ptr() const {
            return reinterpret_cast<SkipListNode*>(value & ~uintptr_t(0x1));
        }
        bool is_marked() const {
            return (value & uintptr_t(0x1)) != 0;
        }
        static MarkedPointer make(SkipListNode* p, bool mark) {
            return MarkedPointer{ reinterpret_cast<uintptr_t>(p) | (mark ? uintptr_t(0x1) : uintptr_t(0x0)) };
        }
    };

    Key key;
    int32_t top_level;
    alignas(CACHE_LINE_SIZE) std::atomic<VersionRecord*> head_version;
    std::atomic<MarkedPointer> next[MAX_SKIPLIST_LEVELS];

    static SkipListNode* create(Key k, int32_t height) {
        size_t node_size = sizeof(SkipListNode);
        void* mem = nullptr;
        if (posix_memalign(&mem, CACHE_LINE_SIZE, node_size) != 0) {
            throw std::bad_alloc();
        }
        return new (mem) SkipListNode(k, height);
    }

    static void destroy(void* ptr) {
        auto* node = reinterpret_cast<SkipListNode*>(ptr);
        node->~SkipListNode();
        std::free(ptr);
    }

private:
    SkipListNode(Key k, int32_t height)
        : key(k), top_level(height), head_version(nullptr) {
        for (int i = 0; i < MAX_SKIPLIST_LEVELS; ++i) {
            next[i].store(MarkedPointer{0}, std::memory_order_relaxed);
        }
    }
};

class ConcurrentMVCCMap {
public:
    ConcurrentMVCCMap() {
        head_ = SkipListNode<uint64_t>::create(0, MAX_SKIPLIST_LEVELS - 1);
        tail_ = SkipListNode<uint64_t>::create(UINT64_MAX, MAX_SKIPLIST_LEVELS - 1);
        for (int i = 0; i < MAX_SKIPLIST_LEVELS; ++i) {
            head_->next[i].store(SkipListNode<uint64_t>::MarkedPointer::make(tail_, false), std::memory_order_relaxed);
        }
    }

    ~ConcurrentMVCCMap() {
        auto* curr = head_;
        while (curr) {
            auto next_ptr = curr->next[0].load(std::memory_order_relaxed).ptr();
            // Free version records attached to curr
            auto* v = curr->head_version.load(std::memory_order_relaxed);
            while (v) {
                auto* vn = v->next_version.load(std::memory_order_relaxed);
                VersionRecord::deallocate(v);
                v = vn;
            }
            SkipListNode<uint64_t>::destroy(curr);
            curr = next_ptr;
        }
    }

    // Strictly wait-free and zero-allocation read path
    bool read(uint64_t key, uint64_t read_timestamp, std::vector<uint8_t>& out_payload) {
        EpochGuard guard;
        SkipListNode<uint64_t>* node = find_node(key);
        if (!node || node->key != key) {
            return false;
        }

        VersionRecord* ver = node->head_version.load(std::memory_order_acquire);
        while (ver != nullptr) {
            if (ver->created_tx_id <= read_timestamp) {
                if (ver->deleted_tx_id > read_timestamp || ver->deleted_tx_id == INF_TX_ID) {
                    out_payload.resize(ver->val_size);
                    std::memcpy(out_payload.data(), ver->payload, ver->val_size);
                    return true; // Visible & active
                }
                return false; // Key was logically deleted at or prior to read_timestamp
            }
            ver = ver->next_version.load(std::memory_order_acquire);
        }
        return false;
    }

    // Returns: 0 = Success, 1 = Conflict/Abort, 2 = Internal Error
    int write(uint64_t key, uint64_t tx_id, uint64_t read_timestamp, std::span<const uint8_t> payload, bool is_delete) {
        EpochGuard guard;
        SkipListNode<uint64_t>* node = get_or_insert_node(key);
        if (!node) return 2;

        while (true) {
            VersionRecord* cur_head = node->head_version.load(std::memory_order_acquire);

            // First-Committer-Wins (FCW) Conflict Detection
            if (cur_head != nullptr) {
                if (cur_head->created_tx_id > read_timestamp) {
                    return 1; // Conflict: A newer committed version exists
                }
                if (cur_head->deleted_tx_id != INF_TX_ID && cur_head->deleted_tx_id > read_timestamp) {
                    return 1; // Conflict: Deleted concurrently
                }
            }

            VersionRecord* new_ver = nullptr;
            if (is_delete) {
                if (!cur_head || cur_head->deleted_tx_id != INF_TX_ID) {
                    return 0; // Already deleted or doesn't exist
                }
                new_ver = VersionRecord::allocate(cur_head->created_tx_id, tx_id, 
                    std::span<const uint8_t>(cur_head->payload, cur_head->val_size));
                new_ver->next_version.store(cur_head->next_version.load(std::memory_order_relaxed), std::memory_order_relaxed);
            } else {
                new_ver = VersionRecord::allocate(tx_id, INF_TX_ID, payload);
                new_ver->next_version.store(cur_head, std::memory_order_relaxed);
            }

            if (node->head_version.compare_exchange_strong(
                    cur_head, new_ver,
                    std::memory_order_acq_rel, std::memory_order_acquire)) {
                return 0; // Version successfully installed
            }

            VersionRecord::deallocate(new_ver);
            // On CAS contention, loop back to re-evaluate FCW
        }
    }

    void vacuum(uint64_t oldest_active_snapshot) {
        EpochGuard guard;
        SkipListNode<uint64_t>* curr = head_->next[0].load(std::memory_order_acquire).ptr();

        while (curr && curr != tail_) {
            VersionRecord* prev = nullptr;
            VersionRecord* ver = curr->head_version.load(std::memory_order_acquire);

            while (ver != nullptr) {
                VersionRecord* next = ver->next_version.load(std::memory_order_acquire);
                if (ver->deleted_tx_id <= oldest_active_snapshot) {
                    // Dead version unlinking
                    if (prev == nullptr) {
                        if (curr->head_version.compare_exchange_strong(
                                ver, next, std::memory_order_acq_rel, std::memory_order_acquire)) {
                            EpochManager::instance().retire(ver, &VersionRecord::deallocate, tl_thread_id);
                            ver = next;
                            continue;
                        }
                    } else {
                        prev->next_version.store(next, std::memory_order_release);
                        EpochManager::instance().retire(ver, &VersionRecord::deallocate, tl_thread_id);
                        ver = next;
                        continue;
                    }
                }
                prev = ver;
                ver = next;
            }
            curr = curr->next[0].load(std::memory_order_acquire).ptr();
        }
    }

private:
    using Node = SkipListNode<uint64_t>;
    using MarkedPtr = Node::MarkedPointer;

    Node* head_;
    Node* tail_;

    int generate_random_level() {
        static thread_local std::mt19937 gen(1337 + tl_thread_id);
        static thread_local std::bernoulli_distribution dist(SKIPLIST_P);
        int lvl = 0;
        while (dist(gen) && lvl < static_cast<int>(MAX_SKIPLIST_LEVELS - 1)) {
            lvl++;
        }
        return lvl;
    }

    bool search_position(uint64_t key, Node** preds, Node** succs) {
    retry:
        Node* pred = head_;
        for (int level = MAX_SKIPLIST_LEVELS - 1; level >= 0; --level) {
            MarkedPtr cur_marked = pred->next[level].load(std::memory_order_acquire);
            Node* curr = cur_marked.ptr();

            while (true) {
                MarkedPtr succ_marked = curr->next[level].load(std::memory_order_acquire);
                while (succ_marked.is_marked()) {
                    // Physical deletion of marked node
                    MarkedPtr expected = MarkedPtr::make(curr, false);
                    if (!pred->next[level].compare_exchange_weak(
                            expected, MarkedPtr::make(succ_marked.ptr(), false),
                            std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }
                    curr = succ_marked.ptr();
                    succ_marked = curr->next[level].load(std::memory_order_acquire);
                }

                if (curr->key < key) {
                    pred = curr;
                    curr = succ_marked.ptr();
                } else {
                    break;
                }
            }
            preds[level] = pred;
            succs[level] = curr;
        }
        return (succs[0]->key == key);
    }

    Node* find_node(uint64_t key) {
        Node* pred = head_;
        for (int level = MAX_SKIPLIST_LEVELS - 1; level >= 0; --level) {
            MarkedPtr cur_marked = pred->next[level].load(std::memory_order_acquire);
            Node* curr = cur_marked.ptr();
            while (true) {
                MarkedPtr succ = curr->next[level].load(std::memory_order_acquire);
                while (succ.is_marked()) {
                    curr = succ.ptr();
                    succ = curr->next[level].load(std::memory_order_acquire);
                }
                if (curr->key < key) {
                    pred = curr;
                    curr = succ.ptr();
                } else {
                    break;
                }
            }
            if (level == 0 && curr->key == key) {
                return curr;
            }
        }
        return nullptr;
    }

    Node* get_or_insert_node(uint64_t key) {
        Node* preds[MAX_SKIPLIST_LEVELS];
        Node* succs[MAX_SKIPLIST_LEVELS];

        while (true) {
            if (search_position(key, preds, succs)) {
                return succs[0];
            }
            int top_level = generate_random_level();
            Node* new_node = Node::create(key, top_level);

            for (int i = 0; i <= top_level; ++i) {
                new_node->next[i].store(MarkedPtr::make(succs[i], false), std::memory_order_relaxed);
            }

            MarkedPtr expected = MarkedPtr::make(succs[0], false);
            if (!preds[0]->next[0].compare_exchange_strong(
                    expected, MarkedPtr::make(new_node, false),
                    std::memory_order_acq_rel, std::memory_order_acquire)) {
                Node::destroy(new_node);
                continue;
            }

            for (int i = 1; i <= top_level; ++i) {
                while (true) {
                    search_position(key, preds, succs);
                    new_node->next[i].store(MarkedPtr::make(succs[i], false), std::memory_order_release);
                    expected = MarkedPtr::make(succs[i], false);
                    if (preds[i]->next[i].compare_exchange_strong(
                            expected, MarkedPtr::make(new_node, false),
                            std::memory_order_acq_rel, std::memory_order_acquire)) {
                        break;
                    }
                }
            }
            return new_node;
        }
    }
};

// ============================================================================
// PART 2: ASYNCHRONOUS GROUP-COMMITTED WAL WITH io_uring
// ============================================================================

enum class LogRecordType : uint8_t {
    TX_BEGIN = 1,
    TX_UPDATE = 2,
    TX_DELETE = 3,
    TX_COMMIT = 4
};

#pragma pack(push, 1)
struct LogHeader {
    uint32_t magic;      // 0x57414C47 (WALG)
    uint32_t crc32;      // CRC32C over payload
    uint64_t lsn;        // Monotonically increasing Log Sequence Number
    uint64_t tx_id;      // Unique transaction ID
    uint8_t  type;       // LogRecordType
    uint32_t data_len;   // Payload length in bytes
};
#pragma pack(pop)

static constexpr uint32_t WAL_MAGIC = 0x57414C47;

struct LogRecordSlot {
    alignas(CACHE_LINE_SIZE) std::atomic<bool> is_ready{false};
    uint64_t lsn{0};
    uint64_t tx_id{0};
    LogRecordType type{LogRecordType::TX_COMMIT};
    uint64_t key{0};
    uint32_t data_len{0};
    uint8_t payload[256];
    std::coroutine_handle<> awaiter_handle{nullptr};
};

class AsyncLogEngine {
public:
    AsyncLogEngine(const std::string& wal_path)
        : current_lsn_(1), flushed_lsn_(0), stop_requested_(false) {
        // Open file with O_DIRECT | O_RDWR | O_CREAT
        fd_ = open(wal_path.c_str(), O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::system_error(errno, std::generic_category(), "Failed to open WAL file with O_DIRECT");
        }

        if (io_uring_queue_init(IO_URING_QUEUE_DEPTH, &ring_, 0) < 0) {
            throw std::runtime_error("Failed to initialize io_uring");
        }

        // Sector-aligned buffer allocation
        if (posix_memalign(reinterpret_cast<void**>(&aligned_buffer_), ALIGN_BLOCK_SIZE, BUFFER_SIZE) != 0) {
            throw std::bad_alloc();
        }
        std::memset(aligned_buffer_, 0, BUFFER_SIZE);

        worker_thread_ = std::thread(&AsyncLogEngine::flush_worker_loop, this);
    }

    ~AsyncLogEngine() {
        stop_requested_.store(true, std::memory_order_release);
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
        io_uring_queue_exit(&ring_);
        if (fd_ >= 0) {
            close(fd_);
        }
        std::free(aligned_buffer_);
    }

    struct LogAwaiter {
        AsyncLogEngine& engine;
        uint64_t target_lsn;

        bool await_ready() const noexcept {
            return engine.flushed_lsn_.load(std::memory_order_acquire) >= target_lsn;
        }

        void await_suspend(std::coroutine_handle<> h) {
            size_t slot = target_lsn % WAL_RING_BUFFER_CAPACITY;
            engine.ring_slots_[slot].awaiter_handle = h;
            // Double-check to prevent lost notifications
            if (engine.flushed_lsn_.load(std::memory_order_acquire) >= target_lsn) {
                engine.ring_slots_[slot].awaiter_handle = nullptr;
                h.resume();
            }
        }

        void await_resume() const noexcept {}
    };

    uint64_t enqueue_record(uint64_t tx_id, LogRecordType type, uint64_t key, std::span<const uint8_t> data) {
        uint64_t assigned_lsn = current_lsn_.fetch_add(1, std::memory_order_relaxed);
        size_t slot_idx = assigned_lsn % WAL_RING_BUFFER_CAPACITY;

        LogRecordSlot& slot = ring_slots_[slot_idx];
        while (slot.is_ready.load(std::memory_order_acquire)) {
            std::this_thread::yield(); // Backpressure wait
        }

        slot.lsn = assigned_lsn;
        slot.tx_id = tx_id;
        slot.type = type;
        slot.key = key;
        slot.data_len = static_cast<uint32_t>(data.size());
        if (!data.empty()) {
            std::memcpy(slot.payload, data.data(), std::min(data.size(), sizeof(slot.payload)));
        }
        slot.awaiter_handle = nullptr;

        slot.is_ready.store(true, std::memory_order_release);
        return assigned_lsn;
    }

    LogAwaiter wait_durable(uint64_t lsn) {
        return LogAwaiter{*this, lsn};
    }

    uint64_t get_flushed_lsn() const {
        return flushed_lsn_.load(std::memory_order_acquire);
    }

private:
    static constexpr size_t BUFFER_SIZE = 4 * 1024 * 1024; // 4MB staging window

    void flush_worker_loop() {
        uint64_t next_drain_lsn = 1;
        off_t file_offset = 0;

        while (!stop_requested_.load(std::memory_order_relaxed)) {
            size_t batch_bytes = 0;
            uint64_t batch_end_lsn = next_drain_lsn;
            std::vector<std::coroutine_handle<>> resumes;

            // Gather completed slots from ring buffer
            while (batch_bytes + sizeof(LogHeader) + sizeof(uint64_t) + 256 < BUFFER_SIZE) {
                size_t slot_idx = batch_end_lsn % WAL_RING_BUFFER_CAPACITY;
                LogRecordSlot& slot = ring_slots_[slot_idx];

                if (!slot.is_ready.load(std::memory_order_acquire) || slot.lsn != batch_end_lsn) {
                    break;
                }

                // Serialize Log Entry
                LogHeader hdr;
                hdr.magic = WAL_MAGIC;
                hdr.lsn = slot.lsn;
                hdr.tx_id = slot.tx_id;
                hdr.type = static_cast<uint8_t>(slot.type);
                hdr.data_len = sizeof(uint64_t) + slot.data_len;

                // CRC calculation over Key + Payload
                uint32_t crc = calculate_crc32c(0, reinterpret_cast<const uint8_t*>(&slot.key), sizeof(uint64_t));
                if (slot.data_len > 0) {
                    crc = calculate_crc32c(crc, slot.payload, slot.data_len);
                }
                hdr.crc32 = crc;

                std::memcpy(aligned_buffer_ + batch_bytes, &hdr, sizeof(LogHeader));
                batch_bytes += sizeof(LogHeader);
                std::memcpy(aligned_buffer_ + batch_bytes, &slot.key, sizeof(uint64_t));
                batch_bytes += sizeof(uint64_t);

                if (slot.data_len > 0) {
                    std::memcpy(aligned_buffer_ + batch_bytes, slot.payload, slot.data_len);
                    batch_bytes += slot.data_len;
                }

                if (slot.awaiter_handle) {
                    resumes.push_back(slot.awaiter_handle);
                }

                batch_end_lsn++;
            }

            if (batch_bytes > 0) {
                // Pad to 4096 sector boundary
                size_t aligned_write_size = (batch_bytes + ALIGN_BLOCK_SIZE - 1) & ~(ALIGN_BLOCK_SIZE - 1);
                std::memset(aligned_buffer_ + batch_bytes, 0, aligned_write_size - batch_bytes);

                // Submit io_uring write
                struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
                while (!sqe) {
                    io_uring_submit(&ring_);
                    sqe = io_uring_get_sqe(&ring_);
                }

                io_uring_prep_write(sqe, fd_, aligned_buffer_, aligned_write_size, file_offset);
                io_uring_submit_and_wait(&ring_, 1);

                struct io_uring_cqe* cqe = nullptr;
                int ret = io_uring_peek_cqe(&ring_, &cqe);
                if (ret == 0 && cqe) {
                    if (cqe->res < 0) {
                        std::cerr << "io_uring write error: " << -cqe->res << std::endl;
                    }
                    io_uring_cqe_seen(&ring_, cqe);
                }

                file_offset += aligned_write_size;
                uint64_t committed_lsn = batch_end_lsn - 1;

                // Clear slots for reuse
                for (uint64_t l = next_drain_lsn; l <= committed_lsn; ++l) {
                    size_t s = l % WAL_RING_BUFFER_CAPACITY;
                    ring_slots_[s].awaiter_handle = nullptr;
                    ring_slots_[s].is_ready.store(false, std::memory_order_release);
                }

                flushed_lsn_.store(committed_lsn, std::memory_order_release);
                next_drain_lsn = batch_end_lsn;

                // Resume coroutines awaiting durability
                for (auto handle : resumes) {
                    if (handle && !handle.done()) {
                        handle.resume();
                    }
                }
            } else {
                std::this_thread::sleep_for(std::chrono::microseconds(50));
            }
        }
    }

    int fd_{-1};
    struct io_uring ring_{};
    uint8_t* aligned_buffer_{nullptr};

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> current_lsn_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> flushed_lsn_;
    std::atomic<bool> stop_requested_;

    std::array<LogRecordSlot, WAL_RING_BUFFER_CAPACITY> ring_slots_{};
    std::thread worker_thread_;
};

